CREATE TABLE IF NOT EXISTS plexus_state.road_jobs (`id` String,`region_id` String,`region` String,`scenario` String,`changes` Array(Tuple(`way_id` Int64,`speed_factor` Float64,`lanes_total` Nullable(Int64),`highway` Nullable(String),`surface` Nullable(String),`speed_kmh` Nullable(Float64))),`status` String,`completed` Int64,`total` Int64,`version` String,`result` Array(Tuple(`before` Float64,`after` Float64,`delta` Float64,`relative_percent` Nullable(Float64),`population` Int64,`settlements` Int64,`changed_edges` Int64,`normalization` Float64,`elapsed_seconds` Float64,`affected_settlements` Nullable(Int64),`money` Array(Tuple(`before_hours` Float64,`after_hours` Float64,`hours_saved_per_trip` Float64,`annual_hours_saved` Float64,`annual_gross_rub` Float64,`annual_net_rub` Float64,`simple_payback_years` Nullable(Float64),`assumptions` Tuple(`origin_point_id` String,`market_city` String,`trips_per_year` Float64,`rub_per_hour` Float64,`capital_cost_rub` Float64,`annual_operating_cost_rub` Float64),`method` String)),`routing_method` String,`settlement_effects` Array(Tuple(`point_id` String,`before` Float64,`after` Float64,`delta` Float64)),`road_cost_method` String,`road_cost_notes` Array(String))),`error` Nullable(String),`addition` Array(Tuple(`source_node` Int64,`target_node` Int64,`travel_hours` Float64,`coordinates` Array(Array(Array(Float64))))),`money_assumptions` Array(Tuple(`origin_point_id` String,`market_city` String,`trips_per_year` Float64,`rub_per_hour` Float64,`capital_cost_rub` Float64,`annual_operating_cost_rub` Float64)),`links` Array(Tuple(`action` String,`network` String,`mode` String,`source` String,`target` String,`hours` Nullable(Float64))),`appraisal_assumptions` Array(Tuple(`passengers` Array(Tuple(`origin_point_id` String,`market_city` String,`trips_per_year` Float64,`rub_per_hour` Float64,`source` String,`basis` String,`origin_name` String)),`scenarios` Array(Tuple(`name` String,`demand_factor` Float64,`value_factor` Float64)),`capital_cost_rub` Float64,`annual_operating_cost_rub` Float64,`horizon_years` Int64,`discount_rate` Float64,`price_year` Int64,`cost_source` String,`freight` Array(Tuple(`name` String,`trips_per_year` Float64,`before_hours` Nullable(Float64),`after_hours` Nullable(Float64),`before_km` Nullable(Float64),`after_km` Nullable(Float64),`rub_per_vehicle_hour` Float64,`rub_per_km` Float64,`source` String,`basis` String,`origin_point_id` String,`market_city` String)))),`appraisal_result` Array(Tuple(`status` String,`travel` Array(Tuple(`origin_point_id` String,`market_city` String,`before_hours` Nullable(Float64),`after_hours` Nullable(Float64))),`unresolved_passenger_flows` Int64,`evaluated_passenger_flows` Int64,`scenarios` Array(Tuple(`name` String,`annual_passenger_hours` Nullable(Float64),`annual_passenger_rub` Nullable(Float64),`annual_vehicle_hours` Nullable(Float64),`annual_vehicle_km` Nullable(Float64),`annual_freight_rub` Nullable(Float64),`annual_gross_rub` Nullable(Float64),`annual_net_rub` Nullable(Float64),`present_benefits_rub` Nullable(Float64),`present_costs_rub` Float64,`net_present_value_rub` Nullable(Float64),`benefit_cost_ratio` Nullable(Float64),`discounted_payback_year` Nullable(Int64))),`method` String,`scope` String,`freight_travel` Array(Tuple(`name` String,`before_hours` Nullable(Float64),`after_hours` Nullable(Float64),`before_km` Nullable(Float64),`after_km` Nullable(Float64))),`unresolved_freight_flows` Int64,`freight_routing_scope` String)),updated UInt64) ENGINE=ReplacingMergeTree(updated) ORDER BY (id) SETTINGS index_granularity=256;

ALTER TABLE plexus_state.road_jobs ADD COLUMN IF NOT EXISTS `links` Array(Tuple(`action` String,`network` String,`mode` String,`source` String,`target` String,`hours` Nullable(Float64))) AFTER `money_assumptions`;

CREATE TABLE IF NOT EXISTS plexus_state.analysis_jobs (`id` String,`job` Tuple(`id` String,`region_id` String,`region` String,`mode` String,`percent` Int64,`fingerprint` String,`status` String,`stage` String,`candidates` Array(Tuple(`way_id` Int64,`name` String,`length_km` Float64,`score` Float64,`isolation_score` Float64,`crosses_boundary` Bool)),`results` Array(Tuple(`candidate` Tuple(`way_id` Int64,`name` String,`length_km` Float64,`score` Float64,`isolation_score` Float64,`crosses_boundary` Bool),`before` Float64,`after` Float64,`delta` Float64,`affected_population` Int64,`isolated_population` Int64,`elapsed_seconds` Float64)),`failures` Array(Tuple(`way_id` Int64,`code` String)),`candidate_count` Int64,`batch_target` Int64,`current_way_id` Nullable(Int64),`completed` Int64,`total` Int64,`elapsed_seconds` Float64,`error` Nullable(String),`compatible` Bool),`boundary` Tuple(`id` String,`name` String,`bounds` Tuple(Float64,Float64,Float64,Float64),`polygons` Array(Array(Array(Tuple(Float64,Float64))))),updated UInt64) ENGINE=ReplacingMergeTree(updated) ORDER BY (id) SETTINGS index_granularity=256;

CREATE TABLE IF NOT EXISTS plexus_state.analysis_details (`analysis_id` String,`way_id` Int64,`detail` Tuple(`result` Tuple(`candidate` Tuple(`way_id` Int64,`name` String,`length_km` Float64,`score` Float64,`isolation_score` Float64,`crosses_boundary` Bool),`before` Float64,`after` Float64,`delta` Float64,`affected_population` Int64,`isolated_population` Int64,`elapsed_seconds` Float64),`lines` Array(Array(Array(Float64))),`settlements` Array(Tuple(`impact` Tuple(`point_id` String,`population` Int64,`before` Float64,`after` Float64,`delta` Float64,`newly_isolated` Bool,`affected` Bool),`name` String,`longitude` Float64,`latitude` Float64))),updated UInt64) ENGINE=ReplacingMergeTree(updated) ORDER BY (analysis_id,way_id) SETTINGS index_granularity=256;
